raveller_count" type="number" min="1" max="65535" name="traveller_count" value="<?= $v('traveller_count') ?>"></div><div class="field"><label for="budget">Estimated budget (INR)</label><input id="budget" type="number" min="0" step="0.01" name="budget" value="<?= $v('budget') ?>"></div><div class="field"><label for="source">Enquiry source</label><select id="source" name="source"><option value="">Select source</option><?php foreach (['Website','WhatsApp','Phone call','Email','Referral','Walk-in','Social media','Other'] as $s): ?><option value="<?= nh_e($s) ?>" <?= ($values['source'] ?? '') === $s ? 'selected' : '' ?>><?= nh_e($s) ?></option><?php endforeach ?></select></div><div class="field"><label for="priority">Priority</label><select id="priority" name="priority"><?php foreach (['low','normal','high','urgent'] as $p): ?><option value="<?= $p ?>" <?= ($values['priority'] ?? 'normal') === $p ? 'selected' : '' ?>><?= ucfirst($p) ?></option><?php endforeach ?></select></div><div class="field"><label for="assigned_to">Assign to</label><select id="assigned_to" name="assigned_to"><option value="">Unassigned</option><?php foreach ($staff as $person): ?><option value="<?= (int) $person['id'] ?>" <?= (string) ($values['assigned_to'] ?? '') === (string) $person['id'] ? 'selected' : '' ?>><?= nh_e($person['name']) ?></option><?php endforeach ?></select></div><div class="field"><label for="currency">Currency</label><select id="currency" name="currency"><option value="INR">INR · Indian Rupee</option><option value="USD">USD · US Dollar</option><option value="AED">AED · UAE Dirham</option><option value="EUR">EUR · Euro</option><option value="GBP">GBP · Pound Sterling</option></select></div><div class="field span-2"><label for="message">Customer's request / message</label><textarea id="message" name="message" placeholder="Travel preferences, destination ideas, requirements…"><?= $v('message') ?></textarea></div><div class="field span-2"><label for="internal_notes">Private team notes</label><textarea id="internal_notes" name="internal_notes" placeholder="Internal notes, not customer-facing…"><?= $v('internal_notes') ?></textarea></div></div><button class="btn" type="submit">Create enquiry</button></form></section>
